import java.util.*;

public final class Solution {
    public static boolean dependenciesValid(List<String> nodes, List<String[]> edges) {
        if (nodes == null || edges == null) {
            return true;
        }

        Set<String> nodeSet = new HashSet<>(nodes);
        if (nodeSet.size() != nodes.size()) {
            return false;
        }

        for (String[] edge : edges) {
            if (edge == null || edge.length != 2) {
                return false;
            }
            String u = edge[0];
            String v = edge[1];
            if (!nodeSet.contains(u) || !nodeSet.contains(v)) {
                return false;
            }
        }

        return !hasCycle(nodes, edges);
    }

    private static boolean hasCycle(List<String> nodes, List<String[]> edges) {
        Map<String, List<String>> adj = new HashMap<>();
        for (String[] edge : edges) {
            String u = edge[0];
            String v = edge[1];
            adj.computeIfAbsent(u, k -> new ArrayList<>()).add(v);
        }

        Set<String> visited = new HashSet<>();
        Set<String> recStack = new HashSet<>();

        for (String node : nodes) {
            if (!visited.contains(node)) {
                if (dfs(node, adj, visited, recStack)) {
                    return true;
                }
            }
        }

        return false;
    }

    private static boolean dfs(String node, Map<String, List<String>> adj, Set<String> visited, Set<String> recStack) {
        visited.add(node);
        recStack.add(node);

        for (String neighbor : adj.get(node)) {
            if (!visited.contains(neighbor)) {
                if (dfs(neighbor, adj, visited, recStack)) {
                    return true;
                }
            } else if (recStack.contains(neighbor)) {
                return true;
            }
        }

        recStack.remove(node);
        return false;
    }
}

